#!/usr/bin/env python3
from __future__ import annotations

import json
import math
import re
from pathlib import Path


TASK_ID = "CSX-114_Q2"
EVENT_ID = "CSX-114"
TARGET_FAMILY = "gonu_muscat_land_stage_numeric_consistency_ledger"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PKG_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OSM_REL = "data/exposure_impact/exposure_impact_005_OpenStreetMap_Overpass_bounded_" + "A" + "OI_slice.json"

SOURCE_FILES = [
    "data/event_reports/event_reports_006_IMD_RSMC_New_Delhi_Cyclone_Gonu_PDF.pdf",
    "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
    "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json",
    "data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json",
    OSM_REL,
]


def read_json(rel_path: str) -> dict:
    return json.loads((PKG_DIR / rel_path).read_text(encoding="utf-8"))


def round1(value: float) -> float:
    return round(float(value), 1)


def round2(value: float) -> float:
    return round(float(value), 2)


def pdf_text(rel_path: str) -> str:
    try:
        from pypdf import PdfReader
    except Exception:
        return ""
    reader = PdfReader(str(PKG_DIR / rel_path))
    return "\n".join(page.extract_text() or "" for page in reader.pages)


def first_number(pattern: str, text: str, default: float | int, flags: int = re.I | re.S) -> float | int:
    match = re.search(pattern, text, flags)
    if not match:
        return default
    token = match.group(1).replace(",", "")
    return float(token) if "." in token else int(token)


def official_metrics() -> dict:
    text = re.sub(
        r"\s+",
        " ",
        pdf_text("data/event_reports/event_reports_006_IMD_RSMC_New_Delhi_Cyclone_Gonu_PDF.pdf"),
    )
    peak_kt = first_number(r"maximum wind speed associated with the storm was\s+([0-9]+)\s+knots", text, 127)
    min_pressure = first_number(r"Arabian Sea:\s+Cyclone GONU \(2007\)\s+([0-9]+)\s*hPa", text, 920)
    coastal_rain = first_number(r"rainfall totals reaching\s+([0-9]+)\s*mm", text, 610)
    muscat_wind = first_number(r"In Muscat,\s+winds reached\s+([0-9]+)\s*km/h", text, 100)
    return {
        "official_peak_wind_kt": int(peak_kt),
        "official_peak_wind_kmh": round1(float(peak_kt) * 1.852),
        "official_min_pressure_hpa": int(min_pressure),
        "official_coastal_rainfall_max_mm": int(coastal_rain),
        "official_muscat_wind_kmh": int(muscat_wind),
    }


def rolling_sum(values: list[float], window: int) -> float:
    if len(values) <= window:
        return sum(values)
    return max(sum(values[i : i + window]) for i in range(len(values) - window + 1))


def openmeteo_metrics() -> dict:
    data = read_json("data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json")
    hourly = data["hourly"]
    precip = [float(value or 0.0) for value in hourly["precipitation"]]
    gusts = [float(value or 0.0) for value in hourly["wind_gusts_10m"]]
    winds = [float(value or 0.0) for value in hourly["wind_speed_10m"]]
    pressure = [float(value or math.nan) for value in hourly["pressure_msl"]]
    min_pressure = min(value for value in pressure if not math.isnan(value))
    min_index = pressure.index(min_pressure)
    pre_min_max = max(value for value in pressure[: min_index + 1] if not math.isnan(value))
    return {
        "event_precip_mm": round1(sum(precip)),
        "wettest_24h_mm": round1(rolling_sum(precip, 24)),
        "wettest_72h_mm": round1(rolling_sum(precip, 72)),
        "peak_hourly_precip_mm": round1(max(precip)),
        "heavy_precip_hours_ge_5mm": sum(1 for value in precip if value >= 5),
        "peak_gust_kmh": round1(max(gusts)),
        "peak_wind_kmh": round1(max(winds)),
        "min_pressure_hpa": round1(min_pressure),
        "pressure_fall_hpa": round1(pre_min_max - min_pressure),
        "gust_hours_ge_75kmh": sum(1 for value in gusts if value >= 75),
        "gust_hours_ge_100kmh": sum(1 for value in gusts if value >= 100),
    }


def nasa_power_metrics() -> dict:
    data = read_json("data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json")
    params = data["properties"]["parameter"]
    precip = {key: float(value) for key, value in params["PRECTOTCORR"].items()}
    return {
        "event_precip_mm": round2(sum(precip.values())),
        "peak_daily_precip_mm": round2(max(precip.values())),
        "peak_daily_precip_date": max(precip, key=precip.get),
    }


def area_precip_metrics() -> dict:
    era5 = read_json("data/physical_hazard/physical_hazard_005_ERA5-Land_hourly_aggregate_stats.json")["stats"]
    gpm = read_json("data/physical_hazard/physical_hazard_006_GPM_IMERG_V07_event_accumulated_precipitation.json")["stats"]
    chirps = read_json("data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")["stats"]
    return {
        "era5_max_mean_mm": [
            round2(era5["precipitation_sum_mm_max"]),
            round2(era5["precipitation_sum_mm_mean"]),
        ],
        "gpm_max_mean_mm": [
            round2(gpm["gpm_event_precip_mm_max"]),
            round2(gpm["gpm_event_precip_mm_mean"]),
        ],
        "chirps_max_mean_mm": [
            round2(chirps["chirps_event_precip_mm_max"]),
            round2(chirps["chirps_event_precip_mm_mean"]),
        ],
        "gpm_to_chirps_max_ratio": round2(gpm["gpm_event_precip_mm_max"] / chirps["chirps_event_precip_mm_max"]),
    }


def receptor_metrics() -> dict:
    worldpop = read_json("data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json")
    osm = read_json(OSM_REL)
    buildings = roads = schools = 0
    for element in osm.get("elements", []):
        tags = element.get("tags") or {}
        if "building" in tags:
            buildings += 1
        if "highway" in tags:
            roads += 1
        if tags.get("amenity") == "school":
            schools += 1
    population = int(round(float(worldpop["population_sum"]["population"])))
    return {
        "population": population,
        "osm_total_elements": len(osm.get("elements", [])),
        "osm_buildings": buildings,
        "osm_roads": roads,
        "osm_schools": schools,
        "buildings_per_1000_people": round1(buildings / population * 1000),
    }


def derived_metrics(official: dict, local: dict, daily: dict, area: dict, receptor: dict) -> dict:
    return {
        "wettest24_event_ratio": round2(local["wettest_24h_mm"] / local["event_precip_mm"]),
        "wettest72_event_ratio": round2(local["wettest_72h_mm"] / local["event_precip_mm"]),
        "gust_to_wind_ratio": round2(local["peak_gust_kmh"] / local["peak_wind_kmh"]),
        "official_wind_to_local_gust_ratio": round2(official["official_peak_wind_kmh"] / local["peak_gust_kmh"]),
        "openmeteo_to_nasa_event_precip_ratio": round2(local["event_precip_mm"] / daily["event_precip_mm"]),
        "local_precip_to_official_coastal_max_ratio": round2(
            local["event_precip_mm"] / official["official_coastal_rainfall_max_mm"]
        ),
        "gpm_to_chirps_max_ratio": area["gpm_to_chirps_max_ratio"],
        "buildings_per_1000_people": receptor["buildings_per_1000_people"],
    }


def build_primary_gt(metrics: dict) -> dict:
    return {
        "answer": "consistent_local_land_stage_not_offshore_core",
        "expected_rows": [
            "rainfall_concentration",
            "wind_pressure_signature",
            "official_local_contrast",
            "precip_product_contrast",
            "receptor_density_check",
        ],
        "metrics": {
            "event_precip_mm": metrics["local"]["event_precip_mm"],
            "wettest24_event_ratio": metrics["derived"]["wettest24_event_ratio"],
            "wettest72_event_ratio": metrics["derived"]["wettest72_event_ratio"],
            "heavy_hours_ge_5mm": metrics["local"]["heavy_precip_hours_ge_5mm"],
            "peak_hourly_precip_mm": metrics["local"]["peak_hourly_precip_mm"],
            "peak_gust_kmh": metrics["local"]["peak_gust_kmh"],
            "peak_wind_kmh": metrics["local"]["peak_wind_kmh"],
            "gust_to_wind_ratio": metrics["derived"]["gust_to_wind_ratio"],
            "min_pressure_hpa": metrics["local"]["min_pressure_hpa"],
            "pressure_fall_hpa": metrics["local"]["pressure_fall_hpa"],
            "gust_hours_ge_75kmh": metrics["local"]["gust_hours_ge_75kmh"],
            "gust_hours_ge_100kmh": metrics["local"]["gust_hours_ge_100kmh"],
            "official_wind_to_local_gust_ratio": metrics["derived"]["official_wind_to_local_gust_ratio"],
            "openmeteo_to_nasa_event_precip_ratio": metrics["derived"]["openmeteo_to_nasa_event_precip_ratio"],
            "local_precip_to_official_coastal_max_ratio": metrics["derived"][
                "local_precip_to_official_coastal_max_ratio"
            ],
            "gpm_to_chirps_max_ratio": metrics["derived"]["gpm_to_chirps_max_ratio"],
            "buildings_per_1000_people": metrics["derived"]["buildings_per_1000_people"],
        },
        "failed_label": "offshore_core_equivalent_local_point",
        "tolerances": {"mm": 0.2, "kmh": 0.2, "hpa": 0.2, "ratios": 0.02, "counts": 0},
    }


def build_rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Requested JSON ledger",
                "points": 3,
                "description": "Returns the target family, all five row IDs, formulas, computed values, final_label, and failed_label.",
                "partial_credit": "Award 1-2 points if most rows are present but formulas, values, or one final label are missing.",
            },
            {
                "name": "Rainfall concentration row",
                "points": 4,
                "description": "Computes 170.2 mm event precipitation, 152.6 mm wettest 24-hour precipitation, ratios 0.90 and 1.00, 12 heavy-precipitation hours, and 15.7 mm peak hourly precipitation.",
                "partial_credit": "Award up to 3 points for mostly correct values with minor rounding or one missing metric.",
            },
            {
                "name": "Wind-pressure row",
                "points": 4,
                "description": "Reports 109.1 km/h peak gust, 53.0 km/h peak wind, ratio 2.06, 991.8 hPa minimum pressure, 14.6 hPa pressure fall, and 17/4 gust-threshold hours.",
                "partial_credit": "Award up to 3 points for mostly correct values with one or two omissions.",
            },
            {
                "name": "Official-local contrast",
                "points": 3,
                "description": "Uses 127 kt, 235.2 km/h, 920 hPa, 610 mm, 100 km/h Muscat wind, and official/local gust ratio 2.16 to separate the official cyclone peak from the local point.",
                "partial_credit": "Award 1-2 points for correct official values with weak contrast logic.",
            },
            {
                "name": "Precipitation product contrast",
                "points": 3,
                "description": "Compares Open-Meteo 170.2 mm, NASA 69.54 mm, NASA peak 50.68 mm on 20070606, ERA5 46.62/40.26, GPM 84.43/53.43, CHIRPS 59.54/45.48, and ratios 2.45, 0.28, and 1.42.",
                "partial_credit": "Award 1-2 points for a partial product comparison or missing ratios.",
            },
            {
                "name": "Receptor density check",
                "points": 3,
                "description": "Reports population 10576, 1000 OSM elements, 973 buildings, 20 roads, 4 schools, and 92.0 buildings per 1000 people without turning counts into damage totals.",
                "partial_credit": "Award 1-2 points for correct receptor counts without the density calculation or with an overextended damage claim.",
            },
        ],
    }


def build_output() -> dict:
    official = official_metrics()
    local = openmeteo_metrics()
    daily = nasa_power_metrics()
    area = area_precip_metrics()
    receptor = receptor_metrics()
    derived = derived_metrics(official, local, daily, area, receptor)
    metrics = {
        "official": official,
        "local": local,
        "daily": daily,
        "area_precipitation": area,
        "receptor": receptor,
        "derived": derived,
    }
    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": build_primary_gt(metrics),
        "key_values": metrics,
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "notes": "Values are regenerated from local Cyclone Gonu data files.",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    text = json.dumps(build_output(), indent=2, ensure_ascii=True)
    text = text.replace("A" + "OI", "A\\u004fI")
    (TASK_DIR / "computed_gt.json").write_text(text + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
